// MARK: - Rendering

enum LucideTint {
    case adaptive
    case white
}

enum LucideRenderer {
    private static var cache: [String: NSImage] = [:]
    private static let lock = NSLock()

    static func image(svg: String, size: CGFloat = 96, white: Bool = true) -> NSImage? {
        let key = "\(Int(size)):\(white ? "w" : "b"):\(svg.hashValue)"
        lock.lock()
        if let cached = cache[key] { lock.unlock(); return cached }
        lock.unlock()

        guard let source = NSImage(data: Data(svg.utf8)) else { return nil }
        let target = NSImage(size: NSSize(width: size, height: size))
        target.lockFocus()
        NSColor.clear.setFill()
        NSRect(x: 0, y: 0, width: size, height: size).fill()
        (white ? NSColor.white : NSColor.black).setFill()
        NSRect(x: 0, y: 0, width: size, height: size).fill()
        source.draw(in: NSRect(x: 0, y: 0, width: size, height: size), from: .zero, operation: .destinationIn, fraction: 1)
        target.unlockFocus()

        lock.lock()
        cache[key] = target
        lock.unlock()
        return target
    }
}

struct LucideIconView: View {
    @Environment(\.colorScheme) private var colorScheme
    let svg: String?
    let size: CGFloat
    var tint: LucideTint = .adaptive

    var body: some View {
        let white = tint == .white || colorScheme == .dark
        if let svg, let image = LucideRenderer.image(svg: svg, white: white) {
            Image(nsImage: image)
                .resizable()
                .interpolation(.high)
                .frame(width: size, height: size)
        }
    }
}

extension BackupBinding {
    var coverIconSVG: String? {
        if let iconSVG, !iconSVG.isEmpty { return iconSVG }
        if let iconName { return LucideCatalog.icons[iconName] }
        return nil
    }
}

// MARK: - Remote icons

enum LucideLink {
    static func iconName(from raw: String) -> String? {
        var value = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !value.isEmpty else { return nil }
        if let url = URL(string: value), url.scheme != nil {
            let components = url.pathComponents.filter { $0 != "/" }
            if let index = components.firstIndex(where: { $0 == "icons" || $0 == "icon" }), index + 1 < components.count {
                value = components[index + 1]
            } else if let last = components.last {
                value = last
            }
        } else {
            value = value.split(separator: "/").last.map(String.init) ?? value
        }
        if value.hasSuffix(".svg") { value = String(value.dropLast(4)) }
        value = value
            .lowercased()
            .replacingOccurrences(of: "_", with: "-")
            .replacingOccurrences(of: " ", with: "-")
        value = value.trimmingCharacters(in: CharacterSet(charactersIn: "-"))
        guard !value.isEmpty,
              value.range(of: "^[a-z0-9-]+$", options: .regularExpression) != nil else { return nil }
        return value
    }
}

enum LucideFetcher {
    static func resolve(_ input: String) async -> (name: String, svg: String)? {
        guard let name = LucideLink.iconName(from: input) else { return nil }
        if let local = LucideCatalog.icons[name] { return (name, local) }

        let bases = [
            "https://unpkg.com/lucide-static@latest/icons/\(name).svg",
            "https://cdn.jsdelivr.net/npm/lucide-static@latest/icons/\(name).svg",
        ]
        for raw in bases {
            guard let url = URL(string: raw) else { continue }
            var request = URLRequest(url: url)
            request.timeoutInterval = 12
            request.cachePolicy = .reloadIgnoringLocalCacheData
            guard let (data, response) = try? await URLSession.shared.data(for: request),
                  let http = response as? HTTPURLResponse,
                  http.statusCode == 200,
                  let svg = String(data: data, encoding: .utf8),
                  svg.contains("<svg") else { continue }
            return (name, svg)
        }
        return nil
    }
}
